import sys
import json
import os
from datetime import datetime

def main():
    if len(sys.argv) < 2:
        print("Usage: python todos.py add <text> or python todos.py list", file=sys.stderr)
        sys.exit(2)

    command = sys.argv[1]
    cache_file = "todos.cache"

    if command == "add":
        if len(sys.argv) < 3:
            print("Usage: python todos.py add <text>", file=sys.stderr)
            sys.exit(2)

        text = " ".join(sys.argv[2:])
        timestamp = datetime.utcnow().isoformat() + "Z"

        if os.path.exists(cache_file):
            with open(cache_file, "r") as f:
                todos = json.load(f)
        else:
            todos = []

        todos.append({"text": text, "timestamp": timestamp})

        with open(cache_file, "w") as f:
            json.dump(todos, f)

        print(f"Added: {text}")
        sys.exit(0)

    elif command == "list":
        if os.path.exists(cache_file):
            with open(cache_file, "r") as f:
                todos = json.load(f)
        else:
            todos = []

        for idx, todo in enumerate(todos, start=1):
            print(f"{idx}. [{todo['timestamp']}] {todo['text']}")

        sys.exit(0)

    else:
        print("Usage: python todos.py add <text> or python todos.py list", file=sys.stderr)
        sys.exit(2)

if __name__ == "__main__":
