import os
from datetime import datetime

def load_todos():
    if os.path.exists("todos.cache"):
        with open("todos.cache", "r") as f:
            return json.load(f)
    return []

def save_todos(todos):
    with open("todos.cache", "w") as f:
        json.dump(todos, f)

def add_todo(text):
    todos = load_todos()
    timestamp = datetime.utcnow().isoformat() + "Z"
    todos.append({"text": text, "timestamp": timestamp})
    save_todos(todos)
    print(f"Added: {text}")

