import sys
import json
import os
from datetime import datetime

CACHE_FILE = "todos.cache"

def load_todos():
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, "r") as f:
            return json.load(f)
    return []

def save_todos(todos):
    with open(CACHE_FILE, "w") as f:
        json.dump(todos, f)

def add_todo(text):
    todos = load_todos()
    timestamp = datetime.utcnow().isoformat() + "Z"
    todos.append({"text": text, "timestamp": timestamp})
    save_todos(todos)
    print(f"Added: {text}")

def list_todos():
    todos = load_todos()
    for idx, todo in enumerate(todos, 1):
        print(f"{idx}. [{todo['timestamp']}] {todo['text']}")

def main():
    if len(sys.argv) < 2:
        print("Usage: python todos.py add <text> or python todos.py list", file=sys.stderr)
        sys.exit(2)

    command = sys.argv[1]
    if command == "add" and len(sys.argv) > 2:
        add_todo(" ".join(sys.argv[2:]))
    elif command == "list":
        list_todos()
    else:
        print("Usage: python todos.py add <text> or python todos.py list", file=sys.stderr)
        sys.exit(2)

